$ErrorActionPreference='Stop';$root=Resolve-Path (Join-Path $PSScriptRoot '..\..');$issues=[System.Collections.Generic.List[string]]::new()
$products=Get-Content (Join-Path $root 'data\products.js') -Raw -Encoding UTF8;$slugs=[regex]::Matches($products,"slug:'([^']+)'")|ForEach-Object{$_.Groups[1].Value}
$sitemap=Get-Content (Join-Path $root 'sitemap.xml') -Raw -Encoding UTF8;$mapped=[regex]::Matches($sitemap,'product\.html\?slug=([^<]+)')|ForEach-Object{$_.Groups[1].Value}
foreach($slug in $slugs){if($slug -notin $mapped){$issues.Add("Product missing from sitemap: $slug")}};foreach($slug in $mapped){if($slug -notin $slugs){$issues.Add("Unknown sitemap product: $slug")}}
foreach($file in Get-ChildItem $root -Filter '*.html' -File){$text=Get-Content $file.FullName -Raw -Encoding UTF8;if($file.Name -notin @('admin.html','404.html','offline.html') -and $text -notmatch '<meta name="description"'){$issues.Add("Missing description: $($file.Name)")};if($file.Name -notin @('admin.html','404.html','offline.html') -and $text -notmatch '<link rel="canonical"'){$issues.Add("Missing canonical: $($file.Name)")}}
if($sitemap -match 'localhost|[A-Z]:\\|<priority>|<changefreq>'){$issues.Add('Sitemap contains forbidden or unjustified values')};if((Get-Content (Join-Path $root 'robots.txt') -Raw) -notmatch 'Sitemap:\s*https://'){$issues.Add('robots.txt lacks an HTTPS sitemap directive')}
[ordered]@{products=$slugs.Count;sitemapProducts=$mapped.Count;issues=$issues.Count;status=if($issues.Count){'FAIL'}else{'PASS'};details=$issues}|ConvertTo-Json -Depth 3;if($issues.Count){exit 1}
